using System.Globalization;
using System.Reflection;
using System.Text;
using PKHeX.Core;

namespace PKConnect.Core.formats;

/// <summary>
/// Maps pokeemerald-expansion item ids (its own ordering, e.g. Leftovers = 472) to PKHeX's modern
/// item ids (Gen 4+ ids are stable across later games) by normalized English name. Backed by
/// <c>pkhexExt/data/expansion_items.json</c>, generated by <c>extract-expansion-species.js</c>.
/// </summary>
public static class ExpansionItemTable
{
    private const string ResourceName = "PKConnect.Core.formats.data.expansion_items.json";

    private static readonly Lazy<(Dictionary<ushort, ushort> ToModern, Dictionary<ushort, ushort> ToExpansion)> maps = new(Load);

    /// <summary>Modern item id for an expansion item id, or 0 if it has no official equivalent.</summary>
    public static ushort ToModern(ushort expansionItem)
        => expansionItem == 0 ? (ushort)0 : maps.Value.ToModern.GetValueOrDefault(expansionItem);

    /// <summary>Expansion item id for a modern item id, or 0 if the expansion doesn't have it.</summary>
    public static ushort ToExpansion(ushort modernItem)
        => modernItem == 0 ? (ushort)0 : maps.Value.ToExpansion.GetValueOrDefault(modernItem);

    private static (Dictionary<ushort, ushort>, Dictionary<ushort, ushort>) Load()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource not found: {ResourceName}");
        var expansionNames = System.Text.Json.JsonSerializer.Deserialize<Dictionary<string, string>>(stream) ?? [];

        var modernByName = new Dictionary<string, ushort>();
        var modernNames = GameInfo.GetStrings("en").Item;
        for (var i = 1; i < modernNames.Count; i++)
        {
            var key = Normalize(modernNames[i]);
            if (key.Length > 0)
                modernByName.TryAdd(key, (ushort)i);
        }

        var toModern = new Dictionary<ushort, ushort>();
        var toExpansion = new Dictionary<ushort, ushort>();
        foreach (var (idText, name) in expansionNames)
        {
            if (!ushort.TryParse(idText, out var expansionId))
                continue;
            if (!modernByName.TryGetValue(Normalize(name), out var modernId))
                continue;
            toModern[expansionId] = modernId;
            toExpansion.TryAdd(modernId, expansionId);
        }
        return (toModern, toExpansion);
    }

    // "Poké Ball" / "POKE_BALL" -> "POKEBALL", "King's Rock" / "KINGS_ROCK" -> "KINGSROCK".
    private static string Normalize(string name)
    {
        var sb = new StringBuilder(name.Length);
        foreach (var c in name.Normalize(NormalizationForm.FormD))
        {
            if (CharUnicodeInfo.GetUnicodeCategory(c) == UnicodeCategory.NonSpacingMark)
                continue;
            if (char.IsLetterOrDigit(c))
                sb.Append(char.ToUpperInvariant(c));
        }
        return sb.ToString();
    }
}
